// Normalize Instagram media -> standard report row schema
const ctx = $('When Executed by Parent').first().json;
const posts = $input.first().json.data || [];

function insight(insights, name) {
  const list = insights && insights.data ? insights.data : [];
  const m = list.find(x => x.name === name);
  return Number(m && m.values && m.values[0] ? m.values[0].value : 0) || 0;
}

function typeLabel(p) {
  if (p.media_product_type === 'REELS') return 'Reel';
  if (p.media_type === 'VIDEO') return 'Video';
  if (p.media_type === 'CAROUSEL_ALBUM') return 'Carousel';
  return 'Photo';
}

return posts
  .filter(p => p.media_product_type !== 'STORY')
  .map(p => ({
    json: {
      platform: 'Instagram',
      channel: ctx.channel,
      account_id: ctx.account_id,
      likes_label: ctx.likes_label || 'Likes',
      id: String(p.id),
      title: (p.caption || 'Instagram Post').split('\n')[0].slice(0, 60),
      type: typeLabel(p),
      views: insight(p.insights, 'views'),
      likes: insight(p.insights, 'likes'),
      comments: insight(p.insights, 'comments'),
      shares: insight(p.insights, 'shares'),
      permalink: p.permalink || '',
      created_at: p.timestamp || null,
    },
  }));
